contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(collectAmount < depositAmount);
        require(minSum == 0);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContract = address(c).balance;
        c.Collect(collectAmount); if (__ESBMC_reverted()) return;
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContract = address(c).balance;
        assert(afterBal == beforeBal - collectAmount && afterContract == beforeContract - collectAmount);
    }

    receive() external payable {}
}

