pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(collectAmount < depositAmount);
        minSum = 0;
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeContract = address(c).balance;
        try c.Collect(collectAmount) {} catch { return; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterContract = address(c).balance;
        assertTrue(afterBal == beforeBal - collectAmount && afterContract == beforeContract - collectAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        _run(depositAmount, minSum, collectAmount);
    }

    receive() external payable {}
}
